export = React;
export as namespace React;

declare namespace React {
  function createContext<T>(defaultValue: T): { Provider: T; Consumer: T };
  function forwardRef<T, P>(render: (props: P, ref: T) => unknown): (props: P) => unknown;

  type ReactNode = string | number | null | undefined;

  type ComponentProps<T> = { className?: string; children?: ReactNode };

  interface HTMLAttributes<T> {
    id?: string;
    className?: string;
  }

  interface ButtonHTMLAttributes<T> extends HTMLAttributes<T> {
    disabled?: boolean;
  }
}
